  @doc ~S"""
  Update or create a configuration for the given MFA method

  `POST /v1/identity/mfa/method/totp/{method_id}`

  ## Arguments

    * `method_id` — The unique identifier for this MFA method.

  ## Options

    * `:algorithm` (string) — The hashing algorithm used to generate the TOTP token. Options include SHA1, SHA256 and SHA512. Defaults to `"SHA1"`.
    * `:digits` (integer) — The number of digits in the generated TOTP token. This value can either be 6 or 8. Defaults to `6`.
    * `:issuer` (string) — The name of the key's issuing organization.
    * `:key_size` (integer) — Determines the size in bytes of the generated key. Defaults to `20`.
    * `:max_validation_attempts` (integer) — Max number of allowed validation attempts.
    * `:method_name` (string) — The unique name identifier for this MFA method.
    * `:period` (seconds) — The length of time used to generate a counter for the TOTP token calculation. Defaults to `30`.
    * `:qr_size` (integer) — The pixel size of the generated square QR code. Defaults to `200`.
    * `:skew` (integer) — The number of delay periods that are allowed when validating a TOTP token. This value can either be 0 or 1. Defaults to `1`.
  """
  @operation "mfa-configure-totp-method"
  @spec mfa_configure_totp_method(ExBao.server(), String.t(), keyword()) ::
          ExBao.Operation.result()
  def mfa_configure_totp_method(server, method_id, opts \\ []) do
    ExBao.Operation.call(
      server,
      :post,
      "identity/mfa/method/totp/#{ExBao.Operation.escape(method_id)}",
      opts,
      body: [
        :algorithm,
        :digits,
        :issuer,
        :key_size,
        :max_validation_attempts,
        :method_name,
        :period,
        :qr_size,
        :skew
      ]
    )
  end

