  @doc ~S"""
  Provides the OIDC Authorization Endpoint.

  `POST /v1/identity/oidc/provider/{name}/authorize`

  ## Arguments

    * `name` — Name of the provider

  ## Options

    * `:client_id` (string, required) — The ID of the requesting client.
    * `:code_challenge` (string) — The code challenge derived from the code verifier.
    * `:code_challenge_method` (string) — The method that was used to derive the code challenge. The following methods are supported: 'S256', 'plain'. Defaults to 'plain'. Defaults to `"plain"`.
    * `:max_age` (integer) — The allowable elapsed time in seconds since the last time the end-user was actively authenticated.
    * `:nonce` (string) — The value that will be returned in the ID token nonce claim after a token exchange.
    * `:redirect_uri` (string, required) — The redirection URI to which the response will be sent.
    * `:response_type` (string, required) — The OIDC authentication flow to be used. The following response types are supported: 'code'
    * `:scope` (string, required) — A space-delimited, case-sensitive list of scopes to be requested. The 'openid' scope is required.
    * `:state` (string) — The value used to maintain state between the authentication request and client.
  """
  @operation "oidc-provider-authorize-with-parameters"
  @spec oidc_provider_authorize_with_parameters(ExBao.server(), String.t(), keyword()) ::
          ExBao.Operation.result()
  def oidc_provider_authorize_with_parameters(server, name, opts \\ []) do
    ExBao.Operation.call(
      server,
      :post,
      "identity/oidc/provider/#{ExBao.Operation.escape(name)}/authorize",
      opts,
      body: [
        :client_id,
        :code_challenge,
        :code_challenge_method,
        :max_age,
        :nonce,
        :redirect_uri,
        :response_type,
        :scope,
        :state
      ],
      required: [:client_id, :redirect_uri, :response_type, :scope]
    )
  end

  @doc ~S"""
  Provides the OIDC Token Endpoint.

  `POST /v1/identity/oidc/provider/{name}/token` — needs no token

  ## Arguments

    * `name` — Name of the provider

  ## Options

    * `:client_id` (string) — The ID of the requesting client.
    * `:client_secret` (string) — The secret of the requesting client.
    * `:code` (string, required) — The authorization code received from the provider's authorization endpoint.
    * `:code_verifier` (string) — The code verifier associated with the authorization code.
    * `:grant_type` (string, required) — The authorization grant type. The following grant types are supported: 'authorization_code','client_credentials'.
    * `:redirect_uri` (string, required) — The callback location where the authentication response was sent.
    * `:scope` (string, required) — A space-delimited, case-sensitive list of scopes to be requested. The 'openid' scope is required. This is used when using in with 'client_credentials' flow
  """
  @operation "oidc-provider-token"
  @spec oidc_provider_token(ExBao.server(), String.t(), keyword()) ::
          ExBao.Operation.result()
