    ExBao.Operation.call(
      server,
      :post,
      "identity/oidc/provider/#{ExBao.Operation.escape(name)}/token",
      opts,
      body: [
        :client_id,
        :client_secret,
        :code,
        :code_verifier,
        :grant_type,
        :redirect_uri,
        :scope
      ],
      required: [:code, :grant_type, :redirect_uri, :scope]
    )
  end

